  ('7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$Natuurkunde$$, $$HAVO$$, $$Zweven op geluid$$, $$HAVO Natuurkunde 2021-II$$),
  ('1c643d9c-afd6-4810-a9a9-198d91d494d4', $$Natuurkunde$$, $$HAVO$$, $$Sirius$$, $$HAVO Natuurkunde 2021-II$$),
  ('222dd8c0-8b68-4041-b83d-13d3facd5174', $$Natuurkunde$$, $$HAVO$$, $$Schommelsprong$$, $$HAVO Natuurkunde 2021-II$$),
  ('02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$Natuurkunde$$, $$HAVO$$, $$Elektrische eierkoker$$, $$HAVO Natuurkunde 2021-II$$),
  ('4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$Natuurkunde$$, $$HAVO$$, $$Stralingsdetectie$$, $$HAVO Natuurkunde 2021-II$$);

insert into practice_context_blocks (id, exercise_id, label, image_url, image_width, text_content, block_type) values
  ('ba19ba39-d9cd-452c-a427-c53ece19434d', '7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$figuur 1 en 2 — opstelling toongenerator, luidspreker en reflector voor zwevende druppels$$, $$natuurkunde-havo-2021-ii-zweven-op-geluid-context1.png$$, 497, $$Het is mogelijk om kleine druppels te laten zweven op geluid. Zie figuur 1. De opstelling die daarvoor nodig is, bestaat uit een toongenerator met een losse luidspreker en een reflector die het geluid terugkaatst. Dit is schematisch weergegeven in figuur 2. Deze figuur is niet op schaal.

figuur 1: foto van een druppel die boven een luidspreker zweeft op een geluidsgolf.
figuur 2: schema van de opstelling — een toongenerator met luidspreker onderin en een reflector bovenin, met daartussen zwevende druppels op vaste hoogtes.

Tussen de luidspreker en de reflector wordt de lucht in trilling gebracht en er ontstaat een golfpatroon van knopen en buiken.

Op de uitwerkbijlage staan twee zinnen over de golven tussen de luidspreker en de reflector.$$, 'inline'),
  ('d415f076-eac6-4bf4-aead-3251d2cd0fec', '7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$figuur 3 — oscillogram signaal toongenerator (22 kHz, 10 μs/hokje)$$, $$natuurkunde-havo-2021-ii-zweven-op-geluid-context2.png$$, 497, $$In figuur 3 is een oscillogram weergegeven van het signaal van de toongenerator tijdens een experiment met de opstelling van figuur 2.

figuur 3: oscillogram van het signaal van de toongenerator; een sinusvormig signaal met ongeveer twee volledige perioden zichtbaar op het scherm.

De horizontale schaalverdeling is 10 μs per hokje.

De toongenerator is ingesteld op 22 kHz.$$, 'inline'),
  ('4e0d5a1c-eac3-45df-85d6-1cc116a312c9', '7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$figuur 4 — foto van zes zwevende druppels in opeenvolgende knopen (22 kHz, 20 °C)$$, $$natuurkunde-havo-2021-ii-zweven-op-geluid-context3.png$$, 497, $$Figuur 4 is een foto van zes zwevende druppels. De afbeelding is niet op ware grootte.

figuur 4: foto van zes druppels die verticaal boven elkaar zweven, elk in een eigen knoop van het golfpatroon.

De zwevende druppels bevinden zich in opeenvolgende knopen. De toongenerator is ingesteld op 22 kHz. De temperatuur van de omgeving is 20 °C.$$, 'inline'),
  ('e682cea0-92c2-47b9-8a8c-37505368ce8a', '7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$figuur 5 — druppel wordt platgedrukt en springt uit elkaar in de geluidsgolf$$, $$natuurkunde-havo-2021-ii-zweven-op-geluid-context4.png$$, 497, $$Onderzocht wordt of met deze methode druppels vloeibaar medicijn opgeslagen kunnen worden. Door het zweven is de kans op vervuiling van het medicijn namelijk kleiner.
Probleem is dat de druppels niet te groot gemaakt mogen worden. Een te grote druppel wordt platgedrukt in de geluidsgolf en springt vervolgens uit elkaar. Zie figuur 5.

figuur 5: drie foto''s op een rij van een druppel aan een naald die steeds verder platgedrukt wordt door de geluidsgolf, tot hij in de derde foto uiteenspat.

Er zijn twee mogelijke oplossingen voor dit probleem:
− de geluidssterkte verlagen,
− de toonhoogte verlagen.

Op de uitwerkbijlage staat het (u,t)-diagram van een signaal waarbij alleen een kleine druppel heel blijft.$$, 'inline'),
  ('012d9183-5ac0-432f-957f-5c390eae8074', '7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$uitwerkbijlage vraag 1 — twee zinnen met aan te kruisen alternatieven (golftype, lopend/staand)$$, $$natuurkunde-havo-2021-ii-zweven-op-geluid-uitwerkbijlage-vraag1.png$$, 497, $$Uitwerkbijlage vraag 1: ''De golf in de lucht tussen de luidspreker en de reflector is een transversale / longitudinale golf.'' en ''De druppels zweven op een lopende / staande golf.'', met de alternatieven om te omcirkelen.$$, 'uitwerkbijlage'),
  ('2154e1bb-7053-4533-8e11-795bb3f070ac', '7a5bdec7-2a30-42b9-8476-1cb86bc7a321', $$uitwerkbijlage vraag 4 — leeg (u,t)-diagram om signaal met beide oplossingen in te schetsen$$, $$natuurkunde-havo-2021-ii-zweven-op-geluid-uitwerkbijlage-vraag4.png$$, 497, $$Uitwerkbijlage vraag 4: een leeg (u,t)-diagram (assen u tegen t, met een reeds getekend voorbeeldsignaal van twee volledige trillingen) waarin de leerling een signaal moet schetsen waarin een lagere geluidssterkte en een lagere toonhoogte gecombineerd zijn, zodat ook een grotere druppel heel blijft.$$, 'uitwerkbijlage'),
  ('fe2e6d62-75fc-4f3b-8c8a-fd7542efc3fb', '1c643d9c-afd6-4810-a9a9-198d91d494d4', $$figuur 1 en 2 — dubbelstersysteem P/Q en analogie autokoplampen (hoek α, 20·afstand aarde-zon, 8,7 lichtjaar, 1,5 m)$$, $$natuurkunde-havo-2021-ii-sirius-context1.png$$, 497, $$Sterren vormen soms een zogenaamd dubbelstersysteem. In een vereenvoudigd dubbelstersysteem bewegen twee sterren in eigen cirkelbanen om een gemeenschappelijk middelpunt M. Zie figuur 1. Sterren P en Q hebben dezelfde omlooptijd.

figuur 1: twee concentrische cirkelbanen om middelpunt M; ster P op de binnenste baan, ster Q op de buitenste baan, beide bewegend in dezelfde draairichting.

Zet in de tabel op de uitwerkbijlage in elke rij een kruisje in de juiste kolom.

De ster Sirius lijkt in de tijd heen en weer te bewegen. In 1844 concludeerden astronomen hieruit dat Sirius een dubbelstersysteem is, bestaande uit Sirius A en Sirius B.
Dat de twee sterren van Sirius toen niet apart van elkaar werden waargenomen, komt doordat de hoek α waaronder Sirius A en Sirius B vanaf de aarde gezien kunnen worden zeer klein is. Deze hoek kan worden vergeleken met de hoek waaronder koplampen van een auto gezien worden. De (gemiddelde) afstand tussen Sirius A en Sirius B is 20 keer zo groot als de afstand tussen de aarde en de zon. Sirius staat op 8,7 lichtjaar van de aarde. De afstand tussen twee koplampen is 1,5 m. Zie figuur 2.

figuur 2: bovenaanzicht van een auto met twee koplampen op 1,5 m afstand van elkaar, gezien onder hoek α op afstand s; daaronder hetzelfde principe met Sirius B en Sirius A op onderlinge afstand 20·Δx(zon-aarde), gezien onder dezelfde hoek α op 8,7 lichtjaar afstand.

Sirius A en Sirius B worden onder een bepaalde hoek α gezien vanaf de aarde.$$, 'inline'),
  ('5aaf8129-6454-4b90-ad12-a70b812320e7', '1c643d9c-afd6-4810-a9a9-198d91d494d4', $$figuur 3 — elliptische baan Sirius B om Sirius A (met de klok mee)$$, $$natuurkunde-havo-2021-ii-sirius-context2.png$$, 497, $$In 1862 werd met een verbeterde telescoop de kleinere Sirius B voor het eerst apart van Sirius A gezien. Daarna noteerden astronomen de positie van Sirius B ten opzichte van Sirius A. Sirius B beschrijft dan een baan om Sirius A met de wijzers van de klok mee. Deze baan is een ellips. Zie figuur 3.

figuur 3: ellipsvormige baan van Sirius B om het vaste punt Sirius A (niet in het midden van de ellips), met een pijl die de bewegingsrichting met de klok mee aangeeft; de actuele positie van Sirius B ligt op de baan dicht bij het punt waar de ellips het dichtst bij Sirius A ligt.$$, 'inline'),
  ('075e80d4-0cd7-44df-bf6d-9429fcb69b44', '1c643d9c-afd6-4810-a9a9-198d91d494d4', $$figuur 4 — tabel massa, straal en λmax van Sirius A en Sirius B (in Mzon en Rzon)$$, $$natuurkunde-havo-2021-ii-sirius-context3.png$$, 497, $$Uit de waarnemingen waren diverse gegevens over Sirius A en Sirius B te bepalen. Zie figuur 4. Gegevens van sterren worden vaak uitgedrukt in vergelijking met onze zon.

figuur 4: tabel met eigenschappen van Sirius A en Sirius B — massa: 2,063·Mzon (A) en 1,018·Mzon (B); straal: 1,8·Rzon (A) en 0,022·Rzon (B); λmax: 293·10⁻⁹ m (A) en 117·10⁻⁹ m (B).

Een van de eigenschappen waarmee sterren onderling vergeleken worden is de dichtheid.$$, 'inline'),
  ('9fbee46b-adb6-4bd9-9914-144dff75efed', '1c643d9c-afd6-4810-a9a9-198d91d494d4', $$figuur 5 — indeling sterren in categorieën op basis van massa m en temperatuur T$$, $$natuurkunde-havo-2021-ii-sirius-context4.png$$, 497, $$Sterren zijn op basis van hun eigenschappen in te delen in categorieën. Een vereenvoudigd overzicht van vijf categorieën sterren staat in figuur 5.

figuur 5: tabel met vijf categorieën sterren (bruine dwerg, rode dwerg, witte dwerg, rode reus, blauwe reus) met bijbehorende massagrenzen (in Mzon) en temperatuurgrenzen (in K); bruine dwerg: 0,01·Mzon < Mster < 0,08·Mzon, Tster < 1,6·10³ K; rode dwerg: 0,08·Mzon < Mster < 0,5·Mzon, 2,3·10³ K < Tster < 3,5·10³ K; witte dwerg: 0,5·Mzon < Mster < 1,4·Mzon, 3,5·10³ K < Tster; rode reus: 0,3·Mzon < Mster < 8·Mzon, Tster < 4,75·10³ K; blauwe reus: 8·Mzon < Mster, 1,0·10⁴ K < Tster < 6,0·10⁴ K.$$, 'inline'),
  ('d98d042b-7803-4b30-b2e2-b2c0a86de80e', '1c643d9c-afd6-4810-a9a9-198d91d494d4', $$uitwerkbijlage vraag 5 — tabel om aan te kruisen welke ster (P, Q, of gelijk) baanstraal/baansnelheid het grootst heeft$$, $$natuurkunde-havo-2021-ii-sirius-uitwerkbijlage-vraag5.png$$, 497, $$Uitwerkbijlage vraag 5: tabel met de eigenschappen ''baanstraal'' en ''baansnelheid'', met voor elke rij drie kolommen om aan te kruisen: ''van ster P het grootst'', ''van ster Q het grootst'', ''voor ster P en Q gelijk''.$$, 'uitwerkbijlage'),
  ('3a4cb41b-c03a-4898-b6f7-a0094f74e8ef', '1c643d9c-afd6-4810-a9a9-198d91d494d4', $$uitwerkbijlage vraag 7 — twee ellipsfiguren om gravitatiekrachten in te tekenen, met invullijnen voor het antwoord$$, $$natuurkunde-havo-2021-ii-sirius-uitwerkbijlage-vraag7.png$$, 497, $$Uitwerkbijlage vraag 7: twee identieke ellipsfiguren met Sirius B op de baan en Sirius A in het brandpunt — in de eerste figuur moet de gravitatiekracht van Sirius B op Sirius A als pijl van 3 cm getekend worden, in de tweede de gravitatiekracht van Sirius A op Sirius B; daaronder invullijnen bij ''Antwoord:'' voor de uitleg of de snelheid van Sirius B ten opzichte van Sirius A toeneemt, afneemt of gelijk blijft.$$, 'uitwerkbijlage'),
  ('fb6e8f02-bf5d-4c81-829e-ade7f02ac094', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$figuur 1 — schema val (A naar S) en schommelbeweging (via evenwichtsstand E) aan touw vanaf brug B$$, $$natuurkunde-havo-2021-ii-schommelsprong-context1.png$$, 497, $$Een schommelsprong is een stunt waarbij een springer aan een speciaal touw van een brug springt. Het touw hangt onder de brug door en is aan de andere zijde bevestigd. Na een korte val recht omlaag gaat de springer daardoor over in een schommelbeweging. Zie de figuren op de uitwerkbijlage.

In figuur 1 zijn schematisch de beginsituatie en de baan van de beweging getekend. Er wordt gesprongen vanaf punt A. Het touw zit vast in punt B. In het laagste punt van de baan gaat de springer door evenwichtsstand E.

figuur 1: schema van een brug tussen twee pijlers; de springer start bovenop de brug in punt A en valt recht naar beneden tot punt S, waar het touw (bevestigd in punt B, aan de andere pijler) strak komt te staan; vanaf S volgt de springer een gebogen slingerbaan (stippellijn) via het laagste punt E naar de andere kant.

Lara voert voor een praktische opdracht metingen uit aan een video van een vrouw die een schommelsprong maakt. Uit de videometing volgt het (v,t)-diagram in figuur 2. Hierbij is de grootte van de snelheid positief weergegeven op de heenweg (van S richting E) en negatief op de terugweg (van E richting S).$$, 'inline'),
  ('8e646415-b18d-4238-b219-545961c8628d', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$foto''s schommelsprong vanaf brug (bij figuur 1 op de uitwerkbijlage)$$, $$natuurkunde-havo-2021-ii-schommelsprong-context2.png$$, 497, $$Drie foto''s van de schommelsprong gezien vanaf de brug: op de eerste foto staat de springer nog op de brugleuning met het touw in de hand, op de tweede foto is de springer aan het touw over het water aan het zwaaien, op de derde foto hangt de springer verder van de brug af, lager boven het water, verder in de schommelbeweging.$$, 'inline'),
  ('5e872b2e-3191-46fc-8cef-bf8249fac172', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$figuur 2 — (v,t)-diagram videometing schommelsprong (v van −13 tot 17 m/s, t van 0 tot 20 s)$$, $$natuurkunde-havo-2021-ii-schommelsprong-context3.png$$, 497, $$figuur 2: (v,t)-diagram van de schommelsprong; v (m s⁻¹) op de verticale as van −20 tot 20, t (s) op de horizontale as van 0 tot 20; de grafiek start bij v=0 op t=0, stijgt lineair tot een piek van ongeveer 17 m/s bij t≈3 s, daalt door nul bij t=5 s naar een minimum van ongeveer −12 m/s bij t≈7,5 s, stijgt weer door nul bij t=10 s naar een tweede (lagere) piek van 10 m/s bij t≈12,5 s, en daalt naar een tweede (ondiepere) dal van ongeveer −8 m/s bij t≈17,5 s.

De schommelsprong begint met een val totdat het touw strak staat. Daarna gaat de beweging over in een schommelbeweging. Zie punt S in figuur 1. Een deel van figuur 2 staat vergroot op de uitwerkbijlage.$$, 'inline'),
  ('b71c55d1-73cc-48ad-a87d-408bee0f85f7', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$formule Fs max = Fz + Fmpz; springer m=60 kg, v=16,8 m/s door E, touwlengte 18 m$$, $$natuurkunde-havo-2021-ii-schommelsprong-context4.png$$, 497, $$Op het moment dat de springer voor de eerste keer in het laagste punt van de baan door de evenwichtsstand E slingert, is de spankracht in het touw maximaal. Deze maximale spankracht Fs max is op dat moment te bepalen met de volgende formule:

Fs max = Fz + Fmpz

De springer (m = 60 kg) gaat met een snelheid van 16,8 m s⁻¹ door de evenwichtsstand E. Het touw heeft een lengte van 18 m.$$, 'inline'),
  ('fd2ddc63-4137-416a-bdf9-50d0d787993c', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$klimmerstouw: diameter 10 mm, treksterkte 2,4·10⁸ N m⁻², max. 20% belast, Fs max=1,5·10³ N$$, $$natuurkunde-havo-2021-ii-schommelsprong-context5.png$$, 497, $$Bergbeklimmers gebruiken speciaal touw om veilig te kunnen klimmen. Een veelgebruikt klimmerstouw heeft een diameter van 10 mm en een treksterkte van 2,4·10⁸ N m⁻². Volgens de fabrikant mag het touw niet zwaarder belast worden dan 20% van de treksterkte. Lara vraagt zich af of dat touw ook sterk genoeg is voor deze schommelsprong met een maximale spankracht van 1,5·10³ N.$$, 'inline'),
  ('aa2c6594-0cc9-4ddf-ba55-28c6a4f40418', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$figuur 3 — vier opties (I t/m IV) voor de resulterende kracht in de uiterste stand van de schommelbeweging$$, $$natuurkunde-havo-2021-ii-schommelsprong-context6.png$$, 497, $$In de uiterste standen van de schommelbeweging is de snelheid nul. In figuur 3 staan vier verschillende opties voor de kracht of krachten op de springer in de uiterste stand. Voor alle krachten is het bevestigingspunt van het touw als aangrijpingspunt gebruikt. De baan waarlangs de springer beweegt, is ook weergegeven.

figuur 3: vier tekeningen (I, II, III, IV) van de springer in de uiterste stand van de schommelbeweging met de baan als stippellijn; optie I toont alleen Fres = 0; optie II toont alleen Fz (omlaag) met Fres = Fz; optie III toont Fz (omlaag), Fspan (langs het touw) en de resulterende Fres tussen beide in; optie IV toont dezelfde drie krachten maar met Fres in een andere richting dan in optie III.$$, 'inline'),
  ('714583d1-1e29-44ad-a6e8-c4f4eac4187a', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$springer m=60 kg ondervindt luchtwrijving; rek in touw verwaarloosd$$, $$natuurkunde-havo-2021-ii-schommelsprong-context7.png$$, 497, $$De springer heeft een massa van 60 kg. Ze ondervindt luchtwrijving waardoor ze afgeremd wordt. De rek in het touw wordt hier verwaarloosd.$$, 'inline'),
  ('f357e7db-eeb4-43be-ae5d-2822f2c71ec9', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$uitwerkbijlage vraag 10 — vergroot deel van figuur 2 (v,t-diagram, t=0-10 s) met invullijnen voor de bepaling$$, $$natuurkunde-havo-2021-ii-schommelsprong-uitwerkbijlage-vraag10.png$$, 497, $$Uitwerkbijlage vraag 10: vergroot deel van figuur 2, het (v,t)-diagram van t=0 tot 10 s (v van −20 tot 20 m s⁻¹); de grafiek loopt van v=0 bij t=0 op naar een piek van ongeveer 17 m/s bij t≈3 s, terug naar v=0 bij t=5 s, naar een minimum van ongeveer −12 m/s bij t≈7,5 s en weer terug naar v=0 bij t=10 s; daaronder een invulregel bij ''Bepaling:'' voor de berekening van de valafstand.$$, 'uitwerkbijlage'),
  ('ab6172fa-f889-42f0-9505-6c6cdc87ee02', '222dd8c0-8b68-4041-b83d-13d3facd5174', $$uitwerkbijlage vraag 14 — figuur 2 met tijdstippen tp en tq aangegeven, invullijnen voor de bepaling$$, $$natuurkunde-havo-2021-ii-schommelsprong-uitwerkbijlage-vraag14.png$$, 497, $$Uitwerkbijlage vraag 14: het volledige (v,t)-diagram van figuur 2 (t=0 tot 20 s, v van −20 tot 20 m s⁻¹) met de tijdstippen tp (op de nuldoorgang net na het eerste dal, rond t≈7,3 s) en tq (op de top van de tweede piek, rond t≈12,5 s) met stippellijnen aangegeven; daaronder invulregels bij ''Bepaling:'' voor de berekening van de arbeid van de luchtwrijvingskracht tussen tp en tq.$$, 'uitwerkbijlage'),
  ('88cb8530-806f-4d03-98a6-a222cb30b11c', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$figuur 1 — eierkoker; werking; schakelaar T (stand I ≤100°C, stand II >100°C); drie ontwerpeisen (S, R+L op 230V, Z)$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context1.png$$, 497, $$Aart heeft een elektrische eierkoker. Zie figuur 1.

figuur 1: foto van een elektrische eierkoker met een metalen deksel los ernaast en vier eieren op een rooster in de behuizing.

Deze eierkoker werkt als volgt:
De eierkoker wordt gevuld met maximaal 7 eieren en een beetje koud water en afgedekt met een deksel.
Na inschakelen wordt het water door een elektrisch verwarmingselement tot het kookpunt verhit en omgezet in waterdamp. De waterdamp verhit de eieren. Zodra het water volledig is verdampt, loopt de temperatuur van het element op tot boven 100 °C. Op dat moment schakelt het verwarmingselement uit en schakelt een zoemer in.

Op de uitwerkbijlage staat een deel van het elektrisch schakelschema getekend. In de eierkoker zit een automatische schakelaar T met twee standen. Als de temperatuur lager is dan of gelijk is aan 100 °C staat de schakelaar in stand I. Als de temperatuur hoger is dan 100 °C staat de schakelaar in stand II.

De eierkoker voldoet aan de volgende drie ontwerpeisen:
1 De eierkoker gaat aan en uit met een schakelaar S.
2 Als het verwarmingselement R aan is, brandt een controlelampje L. Beide werken op een spanning van 230 V.
3 Als de temperatuur boven de 100 °C komt, schakelen R en L uit en schakelt een zoemer Z in.$$, 'inline'),
  ('a70852b4-54e1-4b54-be10-523ca58be425', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$figuur 2 — werktijd t tegen massa water, met en zonder deksel (zonder eieren)$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context2.png$$, 497, $$De eierkoker heeft een deksel met een gaatje waar waterdamp door ontsnapt. Zie figuur 1.

De werktijd t is de tijd tussen het aanzetten van de eierkoker en het automatisch uitschakelen van het verwarmingselement.

Aart meet nog zonder eieren hoe t afhangt van de massa van het water. Hij voert de metingen uit zonder deksel en met deksel. Het resultaat staat in figuur 2.

figuur 2: grafiek van de werktijd t (s, 0-600) tegen de massa water (g, 0-70); twee vrijwel evenwijdige, stijgende rechte lijnen door de meetpunten, ''met deksel'' er licht boven ''zonder deksel'' (bijvoorbeeld bij 40 g: circa 400 s met deksel tegenover circa 360 s zonder deksel).

Aart ziet dat waterdamp op het deksel condenseert en terugloopt in de eierkoker.$$, 'inline'),
  ('85803f4f-bf49-434d-85da-1c7e2fca481f', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$de werktijd t wordt bepaald door het ontwerp; uitwerkbijlage-tabel met mogelijke aanpassingen$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context3.png$$, 497, $$De werktijd t wordt bepaald door het ontwerp van de eierkoker. Op de uitwerkbijlage staat een tabel met mogelijke aanpassingen in het ontwerp.$$, 'inline'),
  ('b2f1aa03-99c6-480f-a101-9176d0419d0b', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$figuur 3 — tabel toe te voegen water per aantal eieren (1-7 eieren, 52-28 gram)$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context4.png$$, 497, $$In de gebruiksaanwijzing vindt Aart een tabel met een opvallende opmerking. Zie figuur 3.

figuur 3: tabel met de opmerking ''Hoe meer eieren er gekookt worden, hoe minder water er toegevoegd hoeft te worden.'' en een rij met het aantal eieren (1 t/m 7) tegenover de bijbehorende hoeveelheid toe te voegen water in gram: 52, 48, 44, 40, 36, 32, 28.$$, 'inline'),
  ('ef39cec0-7f62-42d5-b296-8d44164c15f3', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$figuur 4 — werktijd t tegen massa water voor 1-7 eieren (met deksel) en referentielijn zonder eieren; rendementsdefinitie$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context5.png$$, 497, $$Aart meet t voor 1 tot en met 7 eieren en zet zijn resultaten in een grafiek. Zie figuur 4. Voor iedere meting zijn het deksel en de voorgeschreven hoeveelheid water gebruikt.

figuur 4: grafiek van de werktijd t (s, 0-800) tegen de massa water (g, 0-70); een bovenste lijn ''met deksel, met eieren'' met genummerde meetpunten voor 1 tot en met 7 eieren (bijvoorbeeld 7 eieren bij 28 g water op t≈710 s, aflopend naar 1 ei bij 52 g water op t≈575 s), en een onderste referentielijn ''met deksel, zonder eieren'' (dezelfde lijn als in figuur 2) met stippellijnen die de punten voor 1 ei/52 g en 7 eieren/28 g verticaal verbinden met de onderste lijn.

In figuur 4 staat ook de grafiek van de eerdere metingen met deksel, zonder eieren. In figuur 4 is te zien dat t voor 7 eieren en 28 gram water veel langer is dan voor alleen 28 gram water. Voor 1 ei en 52 gram water is t maar iets langer dan voor alleen 52 gram water.

Het rendement van het koken van de eieren is de verhouding tussen de nuttige energie die door de eieren is opgenomen en de totale elektrische energie die de eierkoker heeft opgenomen.$$, 'inline'),
  ('70713037-dd0a-409d-b8d6-af2339112699', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$verwarmingselement 320 W; een ei neemt ongeveer 14 kJ energie op tijdens het koken$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context6.png$$, 497, $$Het verwarmingselement heeft een vermogen van 320 W.
Op internet leest Aart dat een ei tijdens het koken ongeveer 14 kJ energie opneemt.$$, 'inline'),
  ('67d4955d-0dc5-44d9-87ea-3806a5384b60', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$figuur 5 — vier eieren koken op een gaspit; eierkoker 5,7·10⁻² kWh, gaspit 14 gram aardgas$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-context7.png$$, 497, $$Tot slot wil Aart weten of eieren koken met de elektrische eierkoker energiezuiniger is dan eieren koken in een pan met water op een gaspit. Hij kookt vier eieren op een gaspit. Zie figuur 5.

figuur 5: foto van een pan met kokend water en eieren op een brandende gaspit.

De elektrische eierkoker gebruikt voor het koken van vier eieren 5,7·10⁻² kWh elektrische energie. Met de pan gebruikt Aart 14 gram aardgas.$$, 'inline'),
  ('ae81a7fe-0cd1-40cb-9a9a-3d5e469110c8', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$uitwerkbijlage vraag 15 — onvolledig schakelschema met 230V-bron, schakelaar T (stand I/II) en losse componenten S, R, L, Z$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-uitwerkbijlage-vraag15.png$$, 497, $$Uitwerkbijlage vraag 15: links een lus met een 230V-wisselspanningsbron en de automatische schakelaar T (met contactpunten voor stand I, ≤100°C, en stand II, >100°C); rechts daarvan los getekend de componenten schakelaar S, weerstand R, lampje L en zoemer Z, die de leerling met draden moet verbinden zodat de eierkoker volgens de drie ontwerpeisen functioneert.$$, 'uitwerkbijlage'),
  ('9fa45735-0132-46a9-94a4-4f6e5678e081', '02bd62a5-6e6a-4883-ba6a-735e9d77fade', $$uitwerkbijlage vraag 17 — tabel met drie ontwerpaanpassingen en kolommen ''werktijd neemt af''/''neemt toe''$$, $$natuurkunde-havo-2021-ii-elektrische-eierkoker-uitwerkbijlage-vraag17.png$$, 497, $$Uitwerkbijlage vraag 17: tabel met de kolom ''aanpassing ontwerp'' (rijen: ''een verwarmingselement met een grotere weerstand R'', ''een groter gat in het deksel'', ''warmte-isolatie rondom het deksel'') en twee aankruiskolommen ''de werktijd neemt af'' en ''de werktijd neemt toe''.$$, 'uitwerkbijlage'),
  ('fb7472ca-c796-4c05-bd3e-7a8a818d258f', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$kobalt-60 zendt β- en γ-straling uit; (N,Z)-diagram op uitwerkbijlage$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context1.png$$, 497, $$In een ziekenhuis wordt vaak gewerkt met radioactieve isotopen. Medewerkers moeten daarbij goed in de gaten houden dat ze geen te grote stralingsdosis oplopen. Hiervoor bestaan verschillende vormen van stralingsdetectie.
Een van de isotopen waarmee wordt gewerkt is kobalt-60. Op de uitwerkbijlage staat een (N,Z)-diagram. Hierin is Z het aantal protonen en N het aantal neutronen in een kern.
Kobalt-60 zendt β- en γ-straling uit.$$, 'inline'),
  ('afed14c6-db73-4134-9c88-98141baaa20b', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$figuur 1 en 2 — badge aan kleding met drie vensters (1 mica, 2 karton, 3 lood) voor filmmateriaal$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context2.png$$, 497, $$Bij een bepaalde methode van stralingsdetectie wordt gebruikt gemaakt van een zogenaamde badge. Deze wordt door een medewerker aan de kleding bevestigd. Zie figuur 1.

figuur 1: foto van een badge die met een klem aan de kleding van een medewerker is bevestigd.
figuur 2: schema van een badge met drie ronde vensters naast elkaar, genummerd 1, 2 en 3.

Een badge registreert hoeveel ioniserende straling er op valt. In een bepaalde badge zit filmmateriaal dat steeds donkerder wordt naarmate er meer ioniserende straling op valt. Vóór de film zijn drie verschillende ''vensters'' naast elkaar aangebracht. Zie figuur 2. Deze vensters zijn ieder van een ander materiaal gemaakt:
1 mica
2 karton
3 lood$$, 'inline'),
  ('6b1eac20-cfa1-4b3e-a827-2be9817913f2', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$lood: halveringsdikte 0,061 cm; karton en lood elk 0,183 cm dik$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context3.png$$, 497, $$De badge wordt geraakt door γ-straling afkomstig van een bepaalde bron. Lood heeft een halveringsdikte van 0,061 cm voor deze fotonen. Karton heeft een grotere halveringsdikte. Het karton en het lood hebben elk een dikte van 0,183 cm.$$, 'inline'),
  ('1938db9d-9fb0-4af2-9a09-826b7eff9125', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$α-straling alleen door mica; β-straling door mica én karton$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context4.png$$, 497, $$Na verloop van tijd wordt de badge geopend en is uit de kleur van het filmmateriaal af te leiden welke soort straling de badge heeft geraakt. Gegeven is dat α-straling alleen door mica heen gaat en β-straling zowel door mica als karton.
Op de uitwerkbijlage staan twee badges die ieder gedurende langere tijd door één soort straling geraakt zijn.$$, 'inline'),
  ('f3bffe99-0b7b-4bd4-9980-5b4d70ee2cfb', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$figuur 3 en 4 — geiger-müllerteller (GMT, scherm toont 0,12 μSv/h) en schema telbuis+weerstand R met γ-straling$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context5.png$$, 497, $$De badge wordt tegenwoordig vaak vervangen door een modernere stralingsdetector, de draagbare geiger-müllerteller (GMT). Zie figuur 3.

figuur 3: foto van een draagbare geiger-müllerteller met een digitaal scherm waarop ''0,12 μSv/h'' wordt weergegeven, met daaronder de knoppen ''START'' en ''NEXT''.
figuur 4: schakelschema van de GMT — een telbuis (gevuld met gas, met een venster waar γ-straling op invalt) in serie met een weerstand R en een spanningsmeter U, aangesloten op een spanningsbron.

Een GMT bevat een serieschakeling van een telbuis en een weerstand R. Zie figuur 4. De telbuis is gevuld met een niet-geleidend gas. Over de telbuis staat een spanning. Zolang er geen ioniserende straling op de telbuis valt, werkt deze telbuis als een open schakelaar in de serieschakeling. Wanneer ioniserende straling door het venster valt en het gas raakt, wordt een deel van de gasatomen gesplitst in ionen en elektronen.
Op de uitwerkbijlage staat een tabel over de beweging van de deeltjes in de telbuis.$$, 'inline'),
  ('a389495d-adc7-42a1-bd07-31104c17082f', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$telbuis werkt als gesloten schakelaar zodra straling invalt; spanning U over R verandert$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context6.png$$, 497, $$Door de ioniserende straling werkt de telbuis even als een gesloten schakelaar. Hierdoor verandert de spanning U over weerstand R. Zie figuur 4. Dit wordt door een teller geregistreerd.$$, 'inline'),
  ('d5aa742d-c115-49d4-bee0-4c8174f6c9e6', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$werknemer (ouder dan 18 jaar) beroepshalve blootgesteld, leest meetwaarde 0,12 μSv/h af$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context7.png$$, 497, $$De GMT van figuur 3 wordt gedragen door een werknemer (ouder dan 18 jaar) die beroepshalve te maken heeft met straling. Deze werknemer leest de meetwaarde af van het scherm. Zie figuur 3.$$, 'inline'),
  ('a3d57ada-21d9-43b8-af5b-5050e146b9a8', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$de GMT heeft technische ontwerpvoordelen ten opzichte van de badge voor de bescherming van de medewerker$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-context8.png$$, 497, $$De GMT heeft als technisch ontwerp voordelen ten opzichte van de badge als het gaat om de bescherming van de medewerker.$$, 'inline'),
  ('0dfd24b4-5353-4f88-a7f2-0478951a32c3', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$uitwerkbijlage vraag 21 — (N,Z)-rooosterdiagram (Z=25-35, N=25-35) en invulregel voor de vervalvergelijking$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-uitwerkbijlage-vraag21.png$$, 497, $$Uitwerkbijlage vraag 21: invulregel voor de vervalvergelijking van kobalt-60, gevolgd door een (N,Z)-roosterdiagram met Z (protonen) van 25 tot 35 op de horizontale as en N (neutronen) van 25 tot 35 op de verticale as, waarin de leerling het verval met een pijl moet aangeven.$$, 'uitwerkbijlage'),
  ('bce57f7e-536d-4ce1-b5d9-6f6a339a6c02', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$uitwerkbijlage vraag 23 — twee badges met verschillend gekleurde vensters en aankruistabel α/β/γ$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-uitwerkbijlage-vraag23.png$$, 497, $$Uitwerkbijlage vraag 23: twee badges elk met drie vensters (1, 2, 3) in verschillende grijstinten — badge 1 heeft venster 1 zwart, 2 en 3 grijs; badge 2 heeft venster 1 grijs, 2 en 3 wit (ongekleurd); onder elke badge een tabel met de rijen α, β en γ om de juiste straling te omcirkelen.$$, 'uitwerkbijlage'),
  ('4ffc5a6c-63a0-4fb5-a309-cbda15033f98', '4feb5dee-39bc-4587-8a58-a02ccbb509f9', $$uitwerkbijlage vraag 24 — tabel richting van elektronen, ionen en gasatomen (naar minpool/pluspool/geen vaste richting)$$, $$natuurkunde-havo-2021-ii-stralingsdetectie-uitwerkbijlage-vraag24.png$$, 497, $$Uitwerkbijlage vraag 24: tabel met de rijen ''elektronen'', ''ionen'' en ''gasatomen'' en drie aankruiskolommen: ''bewegen naar de minpool van de telbuis'', ''bewegen naar de pluspool van de telbuis'', ''bewegen niet in een vaste richting''.$$, 'uitwerkbijlage');

