   $$natuurkunde-havo-2021-ii-zweven-op-geluid-vraag3.png$$, 497, $$3 Bereken de werkelijke afstand tussen (het midden van) de eerste en de zesde druppel. 4p$$, array['4e0d5a1c-eac3-45df-85d6-1cc116a312c9']::uuid[]),
