   $$natuurkunde-havo-2021-ii-zweven-op-geluid-vraag4.png$$, 497, $$4 Schets op de uitwerkbijlage in het (u,t)-diagram een signaal waarin beide oplossingen gecombineerd zijn, zodat ook een grotere druppel heel blijft. 2p$$, array['e682cea0-92c2-47b9-8a8c-37505368ce8a','2154e1bb-7053-4533-8e11-795bb3f070ac']::uuid[]),
  ('f45dcd45-5b67-4cbb-9a37-cf120096a61f', '1c643d9c-afd6-4810-a9a9-198d91d494d4', 5,
   $$[{"domain": "Aarde en heelal", "subdomain": "Zonnestelsel en heelal"}]$$::jsonb,
